<?php
/**
 * CM Relay
 * File: api/v1/signup/approve.php
 * Author: Viljem Dvojmoč
 * Assistant: Claude
 * Copyright (c) 2026 Viljem Dvojmoč. All rights reserved.
 *
 * Operator-only (NOT public) - deliberately separate secret from any
 * per-installation bearer token, since this is what actually spends real
 * Channex contract capacity and must never be reachable by a signup
 * applicant themselves. Secret lives in secrets/relay_operator_secret.json
 * ({"secret": "..."}) - not auto-generated by this code, create it by hand
 * like every other file under secrets/ (gitignored, never committed).
 *
 * This is the API-surface equivalent of admin/review_queue.php's "Approve"
 * button - same shared logic (src/signup/signup_lib.php), kept as its own
 * endpoint for automation/non-browser use.
 *
 * GET /api/v1/signup/approve.php - lists pending signups (relay_list_pending_signups()).
 * POST /api/v1/signup/approve.php - body {installation_id}, approves
 *   (relay_approve_external_signup()). Does NOT return a usable bearer
 *   token - it returns a confirmation_token/link; the real token is only
 *   issued when the candidate opens that link (public/confirmation.php).
 */

declare(strict_types=1);

header('Content-Type: application/json; charset=utf-8');

require_once __DIR__ . '/../../../src/signup/signup_lib.php';

function relay_require_operator(): void
{
    $expected = (json_decode((string)@file_get_contents(relay_secrets_root() . '/relay_operator_secret.json'), true))['secret'] ?? null;
    $provided = $_SERVER['HTTP_X_RELAY_OPERATOR_SECRET'] ?? '';

    if ($expected === null) {
        http_response_code(500);
        echo json_encode(['ok' => false, 'error' => 'operator secret not configured']);
        exit;
    }
    if (!hash_equals((string)$expected, (string)$provided)) {
        http_response_code(401);
        echo json_encode(['ok' => false, 'error' => 'unauthorized']);
        exit;
    }
}

relay_require_operator();

if (($_SERVER['REQUEST_METHOD'] ?? '') === 'GET') {
    echo json_encode(['ok' => true, 'pending' => relay_list_pending_signups()]);
    exit;
}

if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {
    http_response_code(405);
    echo json_encode(['ok' => false, 'error' => 'GET or POST required']);
    exit;
}

$body = json_decode(file_get_contents('php://input'), true);
$installationId = trim((string)($body['installation_id'] ?? ''));
if ($installationId === '') {
    http_response_code(400);
    echo json_encode(['ok' => false, 'error' => 'installation_id required']);
    exit;
}

$result = relay_approve_external_signup($installationId);
if (!$result['ok']) {
    http_response_code(in_array($result['error'], ['no pending external installation with that id'], true) ? 404 : 502);
    echo json_encode($result);
    exit;
}

echo json_encode($result);
